WITH filtered AS (SELECT *, CASE WHEN brand IN ('Stark', 'Globex') THEN 'Core' ELSE 'Other' END AS brand_group, CEIL(cost) AS cost_whole, COALESCE(brand, 'N/A') AS brand_filled FROM products WHERE supplier_id IS NOT NULL), remaining_keys AS (SELECT category, id FROM filtered EXCEPT DISTINCT SELECT category, id FROM products WHERE product_name IS NOT NULL), verified AS (SELECT s.* FROM filtered s INNER JOIN remaining_keys k ON s.category = k.category AND s.id = k.id), enriched AS (SELECT e.*, p.supplier_name, p.country FROM verified e LEFT JOIN suppliers p ON e.supplier_id = p.id), enriched_products AS (SELECT id, product_name, category, brand, price, cost, stock_qty, launch_date, tags, supplier_id, brand_group, cost_whole, brand_filled, supplier_name, country, ROUND(price / SUM(price) OVER (PARTITION BY category), 4) AS price_share, PERCENT_RANK() OVER (ORDER BY price DESC NULLS LAST) AS price_percent_rank, PERCENT_RANK() OVER (ORDER BY stock_qty DESC) AS stock_qty_percent_rank, AVG(stock_qty) OVER (PARTITION BY country) AS country_avg_stock_qty FROM enriched), enriched_products_2 AS (SELECT e.*, b.rating, b.city FROM enriched_products e INNER JOIN suppliers b ON e.supplier_id = b.id), with_dims AS (SELECT e.*, d.supplier_name AS supplier_supplier_name, d.country AS supplier_country FROM enriched_products_2 e INNER JOIN suppliers d ON e.supplier_id = d.id) SELECT CASE WHEN price_percent_rank >= 0.61 THEN 'LARGE' ELSE 'SMALL' END AS price_percent_rank_tier, DATE_TRUNC('QUARTER', launch_date) AS quarter_start, ROUND(AVG(price), 2) AS avg_price, COUNT(CASE WHEN supplier_country = 'US' THEN 1 END) AS us_count, ROUND(AVG(cost), 2) AS avg_cost FROM with_dims GROUP BY 1, 2 HAVING ROUND(AVG(price), 2) < 0 ORDER BY quarter_start DESC;
